PREFIX ref: <http://example.org/ref/>
SELECT ?label ?cls ?ts WHERE {
  ?zone brick:hasLabel "DataCenter_bot_ZN_6" .
  ?zone a brick:AirZone .
  optional { ?zone ref:hasTimeseriesId ?ts ; brick:hasTemperature ?t . }
}

PREFIX brick: <http://brick.schema.org/>
SELECT ?uri ?cls ?label WHERE {
  ?uri brick:hasLabel "DataCenter_bot_ZN_6" .
  ?uri a ?cls .
}

PREFIX brick: <http://brick.schema.org/>
SELECT ?uri ?cls ?label WHERE {
  ?uri brick:hasLabel ?label .
  ?uri a ?cls .
  FILTER (contains(str(?label),"ZN_6"))
}

